    "meetings.action_schedule": "Planeeri koosolek",
    "meetings.schedule_failed": "Koosoleku planeerimine ebaõnnestus",
    "meetings.scheduled_ok": "Koosolek planeeritud",
    "meetings.status_cancelled": "Tühistatud",
